package dpswarrior

import "testing"

// Improved Charge "Increases the Rage generated by your Charge ability by
// 3/6": the rage comes with a Charge (charge.go's pre-pull cast, 15 rage
// at rank 3), not with the pull. A warrior whose rotation never Charges -
// Fury and Protection here - gets none of it; one that Charges gets 15
// plus the talent's. Before round 12 the talent paid at Reset whether or
// not Charge was cast, a stand-in from before Charge was a spell
// (round 12, regression-melee lane).
func TestImprovedChargeRageComesWithTheCharge(t *testing.T) {
	var baselineRage float64

	for _, tc := range []struct {
		name  string
		rank  int
		bonus float64
	}{
		{"no talent", 0, 0},
		{"rank 1", 1, 3},
		{"rank 2", 2, 6},
	} {
		t.Run(tc.name, func(t *testing.T) {
			talents := emptyWarriorTalents
			if tc.rank > 0 {
				talents = talentStringWithRank(t, emptyWarriorTalents, "improved_charge", tc.rank)
			}

			war, sim := buildWarriorAndSimForCostTest(t, talents)
			for i := 0; i < 50 && sim.CurrentTime == 0; i++ {
				if sim.Step() {
					break
				}
			}

			if tc.rank == 0 {
				baselineRage = war.CurrentRage()
			}
			if got := war.CurrentRage(); got != baselineRage {
				t.Errorf("rage at the pull without a Charge = %v, want %v: Improved Charge pays only with a Charge", got, baselineRage)
			}

			war.Charge.ApplyEffects(sim, sim.GetTargetUnit(0), war.Charge.Spell)
			if got, want := war.CurrentRage(), baselineRage+15+tc.bonus; got != want {
				t.Errorf("rage after a rank 3 Charge = %v, want %v (15 + %v)", got, want, tc.bonus)
			}
		})
	}
}
